  pros = ARRAY['Video Replay: לחץ על כל שורת תמליל כדי לקפוץ לאותו רגע בהקלטה', 'תמלול בזמן אמת ב-Zoom, Google Meet ו-Microsoft Teams', 'סיכומי פגישות אוטומטיים וחילוץ פריטי פעולה', 'רמה חינמית זמינה עם 300 דקות לחודש — ללא כרטיס אשראי', 'OtterPilot for Sales: תובנות עסקה וסנכרון Salesforce ו-HubSpot (Enterprise)'],
